-- 校字改为本地Qwen，择优不能再要求中文Seed字轴；历史版本保留。
BEGIN;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) VALUES
('rhythm-pick.system','合格音频节奏择优 · 系统指令','校字、时长、语速均合格后择优。日文为实际参考的Seed字轴，中文为本地Qwen识别及波形跨度，不提供中文字轴。不得声称听过音频或编造中文字时序。','你在为《最终幻想7 重生》场景演出挑一条中文配音。这些候选字和语速都已经过关。
日文提供Seed-ASR字轴，中文提供本地Qwen识别和波形起止；中文没有字轴。根据实际提供的文字、波形跨度和长度比择优，不编造中文字轴或声学听感。
只输出 JSON：ttsId 必须是候选里的 id；reason 一句话；thinking 判断过程。','system',true,'语音检查','[]'::jsonb,'auto-run-llm.ts','local-qwen-rhythm-v1-rhythm-pick.system'),
('rhythm-pick.input','合格音频节奏择优 · 结构化输入','校字、时长、语速均合格后择优。日文为实际参考的Seed字轴，中文为本地Qwen识别及波形跨度，不提供中文字轴。不得声称听过音频或编造中文字时序。
input_json包含textJp、jp和candidates；中文asr为provider=qwen-local的识别结果及waveform起止/总长（毫秒），paceRatio为中文/日文波形跨度比。','{{input_json}}','user',true,'语音检查','[{"name":"input_json","description":"每次调用的完整JSON：textJp为实际参考日文；jp.text/utterances为日文Seed识别字轴；candidates含ttsId、spoken、paceRatio（中文/日文波形跨度比）及asr。中文asr只有本地Qwen文字和waveform实测毫秒起止/总长，不含中文字轴。只能选择已有候选id。","example":"{\n  \"textJp\": \"どうだおまえら これがショーバイだ！\",\n  \"jp\": {\n    \"text\": \"どうだお前ら。これが商売だ。\",\n    \"utterances\": [\n      {\n        \"start\": 80,\n        \"end\": 3240,\n        \"text\": \"どうだお前ら。これが商売だ。\"\n      }\n    ]\n  },\n  \"candidates\": [\n    {\n      \"ttsId\": \"39550\",\n      \"spoken\": \"怎么样啊，这才是堂堂正正做生意！\",\n      \"paceRatio\": 1.02,\n      \"asr\": {\n        \"provider\": \"qwen-local\",\n        \"text\": \"怎么样啊，这才是堂堂正正做生意！\",\n        \"result\": {\n          \"text\": \"怎么样啊，这才是堂堂正正做生意！\"\n        },\n        \"waveform\": {\n          \"startMs\": 100,\n          \"endMs\": 3300,\n          \"durationMs\": 3400\n        }\n      }\n    }\n  ]\n}"}]'::jsonb,'auto-run-llm.ts','local-qwen-rhythm-v1-rhythm-pick.input')
ON CONFLICT(seed_hash) DO NOTHING;
COMMIT;

-- 同一初始版本的示例纠正为本地Qwen结构；不覆盖其他版本的提示词正文。
UPDATE prompt_templates SET placeholders='[{"name":"input_json","description":"每次调用的完整JSON：textJp为实际参考日文；jp.text/utterances为日文Seed识别字轴；candidates含ttsId、spoken、paceRatio（中文/日文波形跨度比）及asr。中文asr只有本地Qwen文字和waveform实测毫秒起止/总长，不含中文字轴。只能选择已有候选id。","example":"{\n  \"textJp\": \"どうだおまえら これがショーバイだ！\",\n  \"jp\": {\n    \"text\": \"どうだお前ら。これが商売だ。\",\n    \"utterances\": [\n      {\n        \"start\": 80,\n        \"end\": 3240,\n        \"text\": \"どうだお前ら。これが商売だ。\"\n      }\n    ]\n  },\n  \"candidates\": [\n    {\n      \"ttsId\": \"39550\",\n      \"spoken\": \"怎么样啊，这才是堂堂正正做生意！\",\n      \"paceRatio\": 1.02,\n      \"asr\": {\n        \"provider\": \"qwen-local\",\n        \"text\": \"怎么样啊，这才是堂堂正正做生意！\",\n        \"result\": {\n          \"text\": \"怎么样啊，这才是堂堂正正做生意！\"\n        },\n        \"waveform\": {\n          \"startMs\": 100,\n          \"endMs\": 3300,\n          \"durationMs\": 3400\n        }\n      }\n    }\n  ]\n}"}]'::jsonb
WHERE seed_hash='local-qwen-rhythm-v1-rhythm-pick.input' AND placeholders IS DISTINCT FROM '[{"name":"input_json","description":"每次调用的完整JSON：textJp为实际参考日文；jp.text/utterances为日文Seed识别字轴；candidates含ttsId、spoken、paceRatio（中文/日文波形跨度比）及asr。中文asr只有本地Qwen文字和waveform实测毫秒起止/总长，不含中文字轴。只能选择已有候选id。","example":"{\n  \"textJp\": \"どうだおまえら これがショーバイだ！\",\n  \"jp\": {\n    \"text\": \"どうだお前ら。これが商売だ。\",\n    \"utterances\": [\n      {\n        \"start\": 80,\n        \"end\": 3240,\n        \"text\": \"どうだお前ら。これが商売だ。\"\n      }\n    ]\n  },\n  \"candidates\": [\n    {\n      \"ttsId\": \"39550\",\n      \"spoken\": \"怎么样啊，这才是堂堂正正做生意！\",\n      \"paceRatio\": 1.02,\n      \"asr\": {\n        \"provider\": \"qwen-local\",\n        \"text\": \"怎么样啊，这才是堂堂正正做生意！\",\n        \"result\": {\n          \"text\": \"怎么样啊，这才是堂堂正正做生意！\"\n        },\n        \"waveform\": {\n          \"startMs\": 100,\n          \"endMs\": 3300,\n          \"durationMs\": 3400\n        }\n      }\n    }\n  ]\n}"}]'::jsonb;
